{
  "book_code": "TADAM",
  "verses": [
    {
      "chapter": 14,
      "verse": 3,
      "text_ar": "للرب. فأجبتُ: \"ليس لي حاجةٌ لأن أسجد لآدَمَ\". ولما دأب ميخائيل على حثي على السجود، قلتُ له: \"لماذا تحثني؟ لن أسجد لكائن أدنى وأصغر مني. أنا أقدمُ منه في الخليقة، فقبل أن يُصنع قُدْتُ أنا خُلقْتُ. ومن واجبه هو أن يسجد لي\"."
    },
    {
      "chapter": 15,
      "verse": 1,
      "text_ar": "فلما سمع الملائكة الذين تحت إمرتي بهذا، أبوا أن يسجُدوا له. فقال ميخائيل: \"اسجُدْ لصورة الله، ولكن إن لم تسجد له، فإن الرب الإله سيغضب"
    },
    {
      "chapter": 15,
      "verse": 3,
      "text_ar": "عليك\". فقلتُ: \"إن غضب عليّ، فسأقيم عرشي فوق كواكب السماء وأكون مثل العلي\"."
    },
    {
      "chapter": 16,
      "verse": 1,
      "text_ar": "وغضب الله الرب عليّ وطردني أنا وملائكتي من مجدنا؛ ومن أجل"
    },
    {
      "chapter": 16,
      "verse": 2,
      "text_ar": "أجلكَ طُردنا من مساكننا إلى هذا العالم وطُرِحنا على الأرض. و"
    }
  ]
}
